const text = $json.logs_text || "";

// Extract IPv4 addresses
const ipRegex = /\b(?:\d{1,3}\.){3}\d{1,3}\b/g;
const ips = text.match(ipRegex) || [];

// Extract SHA256 hashes
const sha256Regex = /\b[a-fA-F0-9]{64}\b/g;
const hashes = text.match(sha256Regex) || [];

return [{
  ...$json,
  extracted_indicators: {
    ip_addresses: ips,
    sha256_hashes: hashes
  }
}];

const {
  Document,
  Packer,
  Paragraph,
  HeadingLevel,
  Table,
  TableRow,
  TableCell,
  AlignmentType,
  ImageRun
} = require("docx");

const fs = require("fs");

const data = $input.first().json;
const report = data.parsed_report || {};

// ==========================
// SAFE EXTRACTION
// ==========================

const title = report.title || "Security Incident Report";
const severity = report.severity || "UNKNOWN";
const createdAt = report.created_at || "";
const createdBy = report.created_by || "SOC-AI";

const sections = report.sections || {};
const attacks = report.attacks || [];

const executive = sections.executive_summary || "";
const risk = sections.risk_explanation || "";
const anomaly = sections.anomaly_analysis || "";
const mitigation = sections.mitigation_recommendations || "";
const execution = sections.execution_summary || "";

const attack = attacks[0] || {};

const mitreId = attack.attack_mitre_technique_id || "-";
const mitreName = attack.attack_mitre_technique_name || "-";
const confidence = Math.round((attack.confidence_score || 0) * 100);

// ==========================
// VISUAL BAR FUNCTION
// ==========================

function bar(score) {
  const filled = Math.floor(score / 5);
  return "█".repeat(filled) + "░".repeat(20 - filled);
}

// ==========================
// LOAD LOGO (OPTIONAL)
// ==========================

let logo;
try {
  logo = fs.readFileSync("/files/adnoc_logo.jpeg");
} catch {}

// ==========================
// MITRE TABLE (DYNAMIC)
// ==========================

const mitreTable = new Table({
  rows: [
    new TableRow({
      children: [
        new TableCell({ children: [new Paragraph("Technique ID")] }),
        new TableCell({ children: [new Paragraph("Technique Name")] }),
        new TableCell({ children: [new Paragraph("Confidence (%)")] })
      ]
    }),
    new TableRow({
      children: [
        new TableCell({ children: [new Paragraph(mitreId)] }),
        new TableCell({ children: [new Paragraph(mitreName)] }),
        new TableCell({ children: [new Paragraph(confidence.toString())] })
      ]
    })
  ]
});

// ==========================
// DOCUMENT CHILDREN
// ==========================

const children = [];

// Logo
if (logo) {
  children.push(
    new Paragraph({
      children: [
        new ImageRun({
          data: logo,
          transformation: { width: 200, height: 100 }
        })
      ],
      alignment: AlignmentType.CENTER
    })
  );
}

// Title Section
children.push(
  new Paragraph({
    text: "AI SECURITY REPORT",
    heading: HeadingLevel.HEADING_1,
    alignment: AlignmentType.CENTER
  }),
  new Paragraph(""),
  new Paragraph(`Incident Title: ${title}`),
  new Paragraph(`Severity: ${severity}`),
  new Paragraph(""),
  new Paragraph(`Threat Confidence: ${confidence}%`),
  new Paragraph(bar(confidence)),
  new Paragraph("")
);

// Section Builder
function section(title, content) {
  children.push(
    new Paragraph({
      text: title,
      heading: HeadingLevel.HEADING_2
    }),
    new Paragraph(content || "No data available"),
    new Paragraph("")
  );
}

// Sections (FROM AI JSON — no parsing)
section("EXECUTIVE SUMMARY", executive);
section("RISK EXPLANATION", risk);
section("ANOMALY ANALYSIS", anomaly);
section("MITIGATION RECOMMENDATIONS", mitigation);
section("EXECUTION SUMMARY", execution);

// MITRE Section
children.push(
  new Paragraph({
    text: "MITRE ATT&CK Mapping",
    heading: HeadingLevel.HEADING_2
  }),
  mitreTable,
  new Paragraph("")
);

// Footer
children.push(
  new Paragraph(`Report Generated By: ${createdBy}`),
  new Paragraph(`Date & Time: ${createdAt}`)
);

// ==========================
// BUILD DOCUMENT
// ==========================

const doc = new Document({
  sections: [
    {
      children
    }
  ]
});

const buffer = await Packer.toBuffer(doc);

const binary = await this.helpers.prepareBinaryData(
  buffer,
  `ADNOC_Security_Report_${Date.now()}.docx`,
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
);

return [
  {
    json: {},
    binary: {
      file: binary
    }
  }
];

const data = $input.first().json;

// Initialize score
let score = 0;

// 1. AbuseIPDB score contribution (0–40)
const abuseScore = data.ip_reputation_score || 0;
score += Math.min(abuseScore * 0.4, 40);

// 2. Indicator count contribution (0–25)
const ipCount = data.extracted_indicators?.ip_addresses?.length || 0;
const hashCount = data.extracted_indicators?.sha256_hashes?.length || 0;

const indicatorScore = (ipCount * 5) + (hashCount * 8);
score += Math.min(indicatorScore, 25);

// 3. Severity contribution (0–20)
const severity = (data.severity || "").toLowerCase();

if (severity === "critical") score += 20;
else if (severity === "high") score += 15;
else if (severity === "medium") score += 10;
else if (severity === "low") score += 5;

// 4. Threat intelligence risk level (0–15)
const tiRisk = (data.ti_risk_level || "").toLowerCase();

if (tiRisk === "critical") score += 15;
else if (tiRisk === "high") score += 15;
else if (tiRisk === "medium") score += 10;
else if (tiRisk === "low") score += 5;

// Clamp score
score = Math.min(Math.round(score), 100);

// Determine risk level
let riskLevel = "LOW";

if (score >= 75) riskLevel = "CRITICAL";
else if (score >= 50) riskLevel = "HIGH";
else if (score >= 25) riskLevel = "MEDIUM";

// ✅ Preserve ALL previous fields properly
return [
  {
    json: {
      ...data,
      risk_score: score,
      risk_level: riskLevel,
    }
  }
];

const data = $input.first().json;

const classified_iocs = [];

/*
CLASSIFY IP ADDRESSES
*/
const ip_sources = [
    ...(data.extracted_indicators?.ip_addresses || []),
    ...(data.data?.ipAddress ? [data.data.ipAddress] : [])
];

for (const ip of ip_sources) {

    let category = "External Infrastructure";
    let weight = 30;

    if (
        ip.startsWith("10.") ||
        ip.startsWith("172.") ||
        ip.startsWith("192.")
    ) {
        category = "Internal Infrastructure";
        weight = 5;
    }

    classified_iocs.push({
        value: ip,
        type: "IP Address",
        category,
        risk_weight: weight
    });
}


/*
CLASSIFY FILE HASHES
*/
for (const hash of (data.extracted_indicators?.sha256_hashes || [])) {

    classified_iocs.push({
        value: hash,
        type: "File Hash",
        category: "Malware Artifact",
        risk_weight: 40
    });
}


/*
CLASSIFY DOMAINS
*/
const domain_sources = [
    ...(data.data?.domain ? [data.data.domain] : []),
    ...(data.data?.hostnames || [])
];

for (const domain of domain_sources) {

    classified_iocs.push({
        value: domain,
        type: "Domain",
        category: "Network Indicator",
        risk_weight: 25
    });
}


/*
RETURN RESULT
*/
return [
{
    json: {
        ...data,
        classified_iocs
    }
}
];
